const storageKey='cirdc.ui.language';
const listeners=new Set<()=>void>();
function storedLanguage(value:unknown):Language|undefined{return value==='zh'||value==='en'?value:undefined;}
function browserLanguages():readonly string[]{
 if(typeof navigator==='undefined')return [];
 return navigator.languages?.length?navigator.languages:[navigator.language];
}
export function resolveLanguagePreference(value:unknown,languages:readonly string[]=browserLanguages()):Language{
 const saved=storedLanguage(value);if(saved)return saved;
 for(const tag of languages){const match=typeof tag==='string'&&/^(zh|en)(?:[-_]|$)/i.exec(tag.trim());if(match)return match[1].toLowerCase() as Language;}
 return 'zh';
}
let preference:Language|undefined;
try{preference=storedLanguage(localStorage.getItem(storageKey))}catch{/* Storage may be disabled. */}
let language:Language=resolveLanguagePreference(preference);
const reverse=new Map(Object.entries(messages).map(([zh,en])=>[en,zh]));
export function locale(){return language==='zh'?'zh-CN':'en-US'}
export function t(key:string,values:Record<string,string|number>={}){
 const whitespace=key.match(/^(\s*)(.*?)(\s*)$/s);
 const text=whitespace?whitespace[2]:key;
 const canonical=reverse.get(text)||(text==='Failed to fetch'?'网络连接失败，请检查连接后重试。':text);
 const output=language==='en'?(messages[canonical]||text):canonical;
 return (whitespace?.[1]||'')+output.replace(/\{(\w+)\}/g,(match,name)=>name in values?String(values[name]):match)+(whitespace?.[3]||'');
}
function applyDocument(){document.documentElement.lang=language==='zh'?'zh-CN':'en';document.title=t('CIRDC Pro · 文献数据库')}
export function setLanguage(value:Language,remember=true){
 if(value!=='zh'&&value!=='en')return;
 language=value;
 if(remember){preference=value;try{localStorage.setItem(storageKey,value)}catch{/* In-memory switching still works. */}}
 applyDocument();listeners.forEach(listener=>listener());
}
function subscribe(listener:()=>void){listeners.add(listener);return()=>{listeners.delete(listener)}}
export function useLanguage(){return useSyncExternalStore(subscribe,()=>language,()=>'zh' as Language)}
applyDocument();
window.addEventListener('storage',event=>{
 if(event.key!==storageKey&&event.key!==null)return;
 preference=storedLanguage(event.newValue);setLanguage(resolveLanguagePreference(preference),false);
});
window.addEventListener('languagechange',()=>{if(!preference)setLanguage(resolveLanguagePreference(undefined),false)});
export function localizedText(values:Record<string,string>|undefined,fallback=''){return values?.[language]||t(fallback)}
