export function errorMessage(value:{error?:string;message?:string}){
 if(value.message&&(messages[value.message]||reverse.has(value.message)))return reverse.get(value.message)||value.message;
 return errorKeys[value.error||'']||'操作暂时无法完成，请稍后重试。';
}
